 async function loadLines(){try{const l=await api('/masters/lines');setLines((l||[]).filter((x:LineMaster)=>['NFL','NCL'].includes(masterFactory(x))).sort((a:LineMaster,b:LineMaster)=>masterFactory(a).localeCompare(masterFactory(b))||a.floor.code.localeCompare(b.floor.code,undefined,{numeric:true})||naturalLineCompare(a,b)))}catch(e:any){setError(e.message)}}
 async function loadRows(){try{setError('');const start=d(windowStart)||new Date();const end=addDays(start,Math.max(1,windowDays)-1);const params=new URLSearchParams({from:dateInput(start),to:dateInput(end)});if(factory!=='ALL')params.set('factory',factory);const g=await api(`/planning/gantt?${params.toString()}`);setRows(Array.isArray(g)?g:[])}catch(e:any){setError(e.message)}}
