 async function generate(){setBusy(true);try{const r=await api('/planning/gantt/generate',{method:'POST'});setMsg(r.message);await loadRows()}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 async function update(styleId:string,patch:any){setBusy(true);try{const plan=await api(`/planning/gantt/styles/${styleId}`,{method:'PUT',body:JSON.stringify(patch)});setMsg('Gantt draft reviewed and saved.');setRows(prev=>prev.map(r=>r.styleId===styleId?{...r,ganttPlan:plan}:r));setSelected((prev:any)=>prev?.styleId===styleId?{...prev,ganttPlan:plan}:prev)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 async function approve(ids?:string[]){setBusy(true);try{const r=await api('/planning/gantt/approve',{method:'POST',body:JSON.stringify(ids?.length?{styleIds:ids}:{})});setMsg(r.message);await loadRows()}catch(e:any){setError(e.message)}finally{setBusy(false)}}

 const planned=useMemo(()=>rows.filter(r=>r.ganttPlan?.lineCode&&r.ganttPlan?.startDate&&r.ganttPlan?.finishDate),[rows]);
 const factories=useMemo(()=>Array.from(new Set(lines.map(masterFactory))),[lines]);
 const floors=useMemo(()=>Array.from(new Set(lines.filter(l=>factory==='ALL'||masterFactory(l)===factory).map(l=>`${masterFactory(l)}|${l.floor.code}|${l.floor.name}`))),[lines,factory]);
 const visibleLines=useMemo(()=>lines.filter(l=>(factory==='ALL'||masterFactory(l)===factory)&&(floor==='ALL'||`${masterFactory(l)}|${l.floor.code}|${l.floor.name}`===floor)),[lines,factory,floor]);
 function matchesItem(itemDesc:string,cat:string){
  if(cat==='ALL')return true;
  const d=itemDesc.toLowerCase();
  if(cat==='SWEATSHIRT')return d.includes('sweat')||d.includes('fleece')||d.includes('sweater')||d.includes('pullover');
  if(cat==='TSHIRT')return d.includes('t-shirt')||d.includes('tee')||d.includes('top');
  if(cat==='PANTS')return d.includes('pant')||d.includes('trouser')||d.includes('jogger')||d.includes('bottom')||d.includes('legging');
  if(cat==='POLO')return d.includes('polo')||(d.includes('shirt')&&!d.includes('t-shirt'));
  if(cat==='HOODIE')return d.includes('hood')||d.includes('jacket');
  return true;
 }
 const buyerOptions=useMemo(()=>Array.from(new Set(planned.map(r=>buyerShortCode(r.buyerCode||r.buyer)))).sort(),[planned]);
